// Custom chop using direct SDK
async function chop() {
  const tree = sdk.findNearbyLoc(/^tree$/i);
  if (!tree) return false;
  const before = sdk.getInventory().length;
  const r = await sdk.sendInteractLoc(tree.x, tree.z, tree.id, 1);
  if (!r.success) return false;
  for (let i = 0; i < 50; i++) {
    await new Promise(res => setTimeout(res, 80));
    if (sdk.getInventory().length > before) return true;
  }
  return false;
}

